class Solution { int power(long long base,int exponent,int modulus){long long result=1%modulus;base%=modulus;while(exponent){if(exponent&1)result=result*base%modulus;base=base*base%modulus;exponent>>=1;}return result;}public:vector<int> getGoodIndices(vector<vector<int>>& variables,int target){vector<int> answer;for(int i=0;i<(int)variables.size();++i){auto& row=variables[i];int first=power(row[0],row[1],10);if(power(first,row[2],row[3])==target)answer.push_back(i);}return answer;} };
